-- Restricted maintenance leases. Tokens are generated by PostgreSQL, bound to
-- the current lifecycle fence, and never supplied by HTTP bodies.
ALTER TABLE organization_deletion_jobs ADD COLUMN lease_fence bigint;
ALTER TABLE organization_deletion_jobs ADD CONSTRAINT deletion_job_lease_fence CHECK(lease_fence IS NULL OR lease_fence>0);

CREATE OR REPLACE FUNCTION orgmap_assert_deletion_maintenance(p_org uuid,p_job uuid,p_fence bigint,p_token uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE j record; l record;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'DELETION_READ_COMMITTED_REQUIRED' USING ERRCODE='25001'; END IF;
 IF NOT pg_has_role(session_user,'orgmap_lifecycle_maintenance','MEMBER') OR pg_has_role(session_user,'orgmap_app','MEMBER') OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user AND rolcanlogin AND NOT (rolsuper OR rolbypassrls OR rolcreatedb OR rolcreaterole OR rolreplication)) THEN RAISE EXCEPTION 'DELETION_MAINTENANCE_AUTHORITY_REQUIRED' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.organizations WHERE id=p_org FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DELETION_MAINTENANCE_TARGET_INVALID' USING ERRCODE='42501'; END IF;
 SELECT * INTO l FROM public.organization_lifecycle WHERE organization_id=p_org;
 SELECT * INTO j FROM public.organization_deletion_jobs WHERE organization_id=p_org AND id=p_job FOR UPDATE;
 IF NOT FOUND OR l.state NOT IN ('DELETION_PENDING','PURGING') OR l.fence IS DISTINCT FROM p_fence OR j.lifecycle_fence IS DISTINCT FROM p_fence OR j.lease_fence IS DISTINCT FROM p_fence OR j.ledger_state<>'CONFIRMED' OR j.state<>'RUNNING' OR j.lease_token IS DISTINCT FROM p_token OR p_token IS NULL OR j.lease_until IS NULL OR j.lease_until<=clock_timestamp() THEN RAISE EXCEPTION 'DELETION_MAINTENANCE_LEASE_INVALID' USING ERRCODE='42501'; END IF;
END $$;

CREATE FUNCTION orgmap_deletion_job_claim(p_org uuid,p_job uuid,p_fence bigint,p_ttl_seconds integer)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE j record; l record; new_token uuid:=gen_random_uuid(); new_expiry timestamptz;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'DELETION_READ_COMMITTED_REQUIRED' USING ERRCODE='25001'; END IF;
 IF NOT pg_has_role(session_user,'orgmap_lifecycle_maintenance','MEMBER') OR pg_has_role(session_user,'orgmap_app','MEMBER') OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user AND rolcanlogin AND NOT (rolsuper OR rolbypassrls OR rolcreatedb OR rolcreaterole OR rolreplication)) THEN RAISE EXCEPTION 'DELETION_MAINTENANCE_AUTHORITY_REQUIRED' USING ERRCODE='42501'; END IF;
 IF p_ttl_seconds IS NULL OR p_ttl_seconds<5 OR p_ttl_seconds>300 THEN RAISE EXCEPTION 'DELETION_LEASE_TTL_INVALID' USING ERRCODE='22023'; END IF;
 PERFORM 1 FROM public.organizations WHERE id=p_org FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DELETION_MAINTENANCE_TARGET_INVALID' USING ERRCODE='42501'; END IF;
 SELECT * INTO l FROM public.organization_lifecycle WHERE organization_id=p_org;
 SELECT * INTO j FROM public.organization_deletion_jobs WHERE organization_id=p_org AND id=p_job FOR UPDATE;
 IF NOT FOUND OR l.state NOT IN ('DELETION_PENDING','PURGING') OR l.fence IS DISTINCT FROM p_fence OR j.lifecycle_fence IS DISTINCT FROM p_fence OR j.ledger_state<>'CONFIRMED' OR j.ledger_authority_id IS NULL OR j.ledger_record_sha256 IS NULL OR j.state NOT IN ('PENDING','FAILED','RUNNING') OR j.phase='COMPLETED' OR NOT EXISTS(SELECT 1 FROM public.organization_runtime_identity i JOIN public.organization_runtime_mode m USING(singleton) WHERE i.singleton AND m.managed AND i.authority_id=j.ledger_authority_id) THEN RAISE EXCEPTION 'DELETION_JOB_CLAIM_INVALID' USING ERRCODE='42501'; END IF;
 -- A live lease without a recorded fence is legacy and stays blocked. A lease
 -- bound to another fence cannot authorize any current-fence maintenance.
 IF j.lease_token IS NOT NULL AND j.lease_until>clock_timestamp() AND (j.lease_fence IS NULL OR j.lease_fence=p_fence) THEN RAISE EXCEPTION 'DELETION_JOB_LEASE_HELD' USING ERRCODE='55P03'; END IF;
 new_expiry:=clock_timestamp()+make_interval(secs=>p_ttl_seconds);
 UPDATE public.organization_deletion_jobs SET state='RUNNING',lease_token=new_token,lease_fence=p_fence,lease_until=new_expiry,error_code=NULL,version=version+1,updated_at=clock_timestamp() WHERE organization_id=p_org AND id=p_job;
 RETURN jsonb_build_object('leaseToken',new_token,'leaseUntil',new_expiry,'phase',j.phase,'fence',p_fence::text);
END $$;
CREATE FUNCTION orgmap_deletion_job_heartbeat(p_org uuid,p_job uuid,p_fence bigint,p_token uuid,p_ttl_seconds integer)
RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE expiry timestamptz;
BEGIN
 IF p_ttl_seconds IS NULL OR p_ttl_seconds<5 OR p_ttl_seconds>300 THEN RAISE EXCEPTION 'DELETION_LEASE_TTL_INVALID' USING ERRCODE='22023'; END IF;
 PERFORM public.orgmap_assert_deletion_maintenance(p_org,p_job,p_fence,p_token);
 UPDATE public.organization_deletion_jobs SET lease_until=clock_timestamp()+make_interval(secs=>p_ttl_seconds),updated_at=clock_timestamp()
 WHERE organization_id=p_org AND id=p_job AND lease_token=p_token AND lease_fence=p_fence AND lease_until>clock_timestamp()
 RETURNING lease_until INTO expiry;
 IF NOT FOUND THEN RAISE EXCEPTION 'DELETION_MAINTENANCE_LEASE_INVALID' USING ERRCODE='42501'; END IF;
 RETURN expiry;
END $$;
CREATE FUNCTION orgmap_deletion_job_yield(p_org uuid,p_job uuid,p_fence bigint,p_token uuid,p_error_code text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
BEGIN
 IF p_error_code IS NOT NULL AND p_error_code !~ '^[A-Z][A-Z0-9_]{0,79}$' THEN RAISE EXCEPTION 'DELETION_ERROR_CODE_INVALID' USING ERRCODE='22023'; END IF;
 PERFORM public.orgmap_assert_deletion_maintenance(p_org,p_job,p_fence,p_token);
 UPDATE public.organization_deletion_jobs SET state=CASE WHEN p_error_code IS NULL THEN 'PENDING' ELSE 'FAILED' END,error_code=p_error_code,lease_token=NULL,lease_fence=NULL,lease_until=NULL,version=version+1,updated_at=clock_timestamp() WHERE organization_id=p_org AND id=p_job AND lease_token=p_token AND lease_fence=p_fence AND lease_until>clock_timestamp();
 IF NOT FOUND THEN RAISE EXCEPTION 'DELETION_MAINTENANCE_LEASE_INVALID' USING ERRCODE='42501'; END IF;
END $$;
REVOKE ALL ON FUNCTION orgmap_deletion_job_claim(uuid,uuid,bigint,integer),orgmap_deletion_job_heartbeat(uuid,uuid,bigint,uuid,integer),orgmap_deletion_job_yield(uuid,uuid,bigint,uuid,text) FROM PUBLIC,orgmap_app;
GRANT EXECUTE ON FUNCTION orgmap_deletion_job_claim(uuid,uuid,bigint,integer),orgmap_deletion_job_heartbeat(uuid,uuid,bigint,uuid,integer),orgmap_deletion_job_yield(uuid,uuid,bigint,uuid,text) TO orgmap_lifecycle_maintenance;
